function ParseNestedParens(parenString: string): array of integer;
{ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three. }
begin
  Result := new integer[10];
  var i := 0;
  var max := 0;
  foreach var c in parenString.Split(' ') do
  begin
    var count := 0;
    var level := 0;
    foreach var cc in c.Reverse do
    begin
      if cc = '(' then
        level += 1
      else
      begin
        count += 1;
        if level > max then
          max := level;
      end;
    end;
    Result[i] := max;
    i += 1;
  end;
end.


