function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var rev_str := str.Reverse;
  var i := 0;
  while i < n do
  begin
    if str.Substring(i,n-i) = rev_str.Substring(0,n-i) then
      break;
    i += 1;
  end;
  Result := str + str.Substring(0,i).Reverse;
end;


