  var (a, e, o) := (l, nil, nil);
  if b.Contains(True) then
    a := l.Where((x, i) -> b[i] and i mod 3 = 0).ToArray
  else
    a := l.Where((x, i) -> b[i]).ToArray;
  if b.Contains(True) then
    o := a.Where((x, i) -> b[i] and i mod 3 = 2).OrderBy(x -> x).ToArray
  else
    o := a.Where((x, i) -> b[i] and i mod 3 = 2).OrderBy(x -> x).ToArray;
  if b.Contains(True) then
    e := a.Where((x, i) -> b[i] and i mod 3 = 1).OrderByDescending(x -> x).ToArray
  else
    e := a.Where((x, i) -> b[i] and i mod 3 = 1).OrderByDescending(x -> x).ToArray;
