function Median(l: array of integer): real;
begin
  var n := l.Length;
  if n = 0 then
    Result := 0
  else
  begin
    var (a, b) := (l[^1], l[1]);
    var (c, d) := (l[^2], l[2]);
    if a < b then
      (a, b) := (b, a);
    if c < d then
      (c, d) := (d, c);
    if a < c then
      (a, c) := (c, a)
    else if b > c then
      (b, c) := (c, b)
    else if b < a then
      (b, a) := (a, b)
    else if d < a then
      (d, a) := (a, d)
    else if d > c then
      (d, c) := (c, d)
    else Result := b
  end
end;


