function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var d := [[0; 0; 0]];
  var dp := [[integer.MaxValue; 0; 0]];
  for var i := 0 to n - 1 do
    d := d + [[grid[i][0]; 0; 0]];
  for var j := 0 to m - 1 do
    dp := dp + [[integer.MaxValue; 0; 0]];
  dp[0][0] := 0;
  var (i, j) := (0, 0);
  var cnt := 0;
  while cnt < k do
  begin
    var min := integer.MaxValue;
    for var dx := -1 to 1 do
    for var dy := -1 to 1 do
      if (dx <> 0) or (dy <> 0) then
      begin
        var (ni, nj) := (i + dx, j + dy);
        if (ni >= 0) and (ni < n) and (nj >= 0) and (nj < m) and (dp[ni][nj] <> integer.MaxValue) then
          if d[i][1] = d[ni][0] and d[ni][1] = d[j][0] and dp[ni][nj] + 1 < dp[i][j] then
            dp[i][j] := dp[ni][nj] + 1;
        if (min = integer.MaxValue) or (min > d[i][1]) then
          min := d[i][1];
      end;
    if min = integer.MaxValue then
      break;
    cnt += 1;
    var (ni, nj) := (0, 0);
    for var x := 0 to n - 1 do
      for var y := 0 to m - 1 do
        if (d[x][0] = grid[i][j]) and (d[x][1] = d[i][0]) and (d[x][1] = d[j][0]) and (dp[x][y] = dp[i][j]) then
        begin
          (ni, nj) := (x, y);
          break;
        end;
    (i, j) := (ni, nj);
  end;
  var res := [];
  (i, j) := (n - 1, m - 1);
  var c := k;
  while c > 0 do
  begin
    res.Add(grid[i][j]);
    (i, j) := (i - 1, j - 1);
    c -= 1;
  end;
  res.Reverse;
  Result := res;
end;


