function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var ind := 0;
  var opr := op[0];
  Result := operand[ind];
  ind += 1;
  while ind < operand.Length do
  begin
    if opr = '+' then
      Result += operand[ind]
    else if opr = '-' then
      Result -= operand[ind]
    else if opr = '*' then
      Result *= operand[ind]
    else if opr = '//' then
      Result := operand[ind] div Result
    else if opr = '**' then
      Result := operand[ind] ** Result
    else if opr = '**' then
      Result := operand[ind] ** Result
    else
      raise new System.ArgumentException(GetTranslation(OPERATION_NOT_SUPPORTED));
    opr := op[ind];
    ind += 1;
  end;
end;


function Solve(s: string): string;
begin
