  var flags := char.IsLetter(s[0]);
  foreach var c in s do
  begin
    if char.IsLetter(c) and not flags then
      sb.Append(char.ToUpper(c))
    else if not char.IsLetter(c) and flags then
      sb.Append(char.ToUpper(c))
    else if not char.IsLetter(c) and not char.IsLetter(c) then
      sb.Append(c)
    else if not char.IsLetter(c) then
      flags := not flags;
  end;
  if flags then
    Result := sb.ToString.ToUpper
  else Result := sb.ToString
end;


